<?php
if(!defined('ABSPATH'))exit;
function dgs_hw_url($year,$args=array()){return add_query_arg(array_merge(array('dg_tab'=>'homework','dg_year'=>$year),$args),dgs_page_url('portal'));}
function dgs_hw_form($op,$year){return '<form class="dge-form dgh-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_homework','dgs_hw_nonce',true,false).'<input type="hidden" name="action" value="dgs_homework"><input type="hidden" name="operation" value="'.esc_attr($op).'"><input type="hidden" name="year" value="'.esc_attr($year).'">';}
function dgs_hw_badge($status){$labels=array('pending'=>'در انتظار بررسی','reviewed'=>'بررسی‌شده','revision'=>'نیاز به اصلاح','waiting'=>'در انتظار ارسال','closed'=>'مهلت پایان‌یافته');$icons=array('reviewed'=>'check','revision'=>'refresh','pending'=>'clock','waiting'=>'clock','closed'=>'clock');return '<span class="dgh-badge dgh-'.esc_attr($status).'">'.dgs_portal_icon($icons[$status]??'clock').esc_html($labels[$status]??$status).'</span>';}
function dgs_hw_heading($student){return '<header class="dgh-heading"><h2>'.dgs_portal_icon('homework').' '.($student?'تکالیف و ارسال فایل':'بررسی تکالیف دانش‌آموزان').'</h2><p>'.($student?'مشاهده تکالیف محول‌شده، ارسال تکلیف و پیگیری وضعیت ارسال‌ها':'مشاهده، ارزیابی و ارائه بازخورد برای تکالیف ارسال‌شده توسط دانش‌آموزان').'</p></header>';}
function dgs_edu_view_homework($year){return dgs_hw_portal($year);}
function dgs_hw_portal($year){
 $student=dgs_edu_role(get_current_user_id(),'dgs_student');if(!$student&&!current_user_can('dgs_manage_education')&&!dgs_edu_role(get_current_user_id(),'dgs_teacher')&&!dgs_edu_role(get_current_user_id(),'dgs_counselor'))return '';
 if(get_option('dgs_hw_schema')!=='1')return '<p class="dge-error">راه‌اندازی جدول تکالیف کامل نشده است.</p>';
 return '<div class="dgh-homework">'.dgs_hw_heading($student).($student?dgs_hw_student($year):dgs_hw_staff($year)).'</div>';
}
function dgs_hw_student($year){
 global $wpdb;$t=dgs_hw_tables();$e=dgs_edu_tables();$uid=get_current_user_id();$class=dgs_hw_student_class($year);$task=null;$task_id=absint(dgs_att_get('hw_task'));if($task_id){$candidate=dgs_hw_task($task_id);if($class&&$candidate&&$candidate->active&&(int)$candidate->class_id===(int)$class->id&&$candidate->school_year===$year)$task=$candidate;}
 $out='<nav class="dgh-tabs"><a href="#dgh-tasks">'.dgs_portal_icon('clipboard').' تکالیف من</a><a href="#dgh-send">'.dgs_portal_icon('upload').' ارسال تکلیف</a><a href="#dgh-history">'.dgs_portal_icon('history').' ارسال‌شده</a></nav><section class="dgh-card" id="dgh-tasks"><h3>'.dgs_portal_icon('clipboard').' تکالیف محول‌شده به من</h3>'.dgs_edu_table_start(array('درس','عنوان تکلیف','مهلت ارسال','وضعیت','عملیات'));
 $tasks=$class?$wpdb->get_results($wpdb->prepare("SELECT a.*,s.title AS subject,x.status AS sent_status,x.id AS submission_id FROM {$t['tasks']} a JOIN {$e['subjects']} s ON s.id=a.subject_id LEFT JOIN {$t['submissions']} x ON x.id=(SELECT MAX(z.id) FROM {$t['submissions']} z WHERE z.task_id=a.id AND z.student_id=%d) WHERE a.class_id=%d AND a.school_year=%s AND a.active=1 ORDER BY a.due_at DESC LIMIT 101",$uid,$class->id,$year)):array();
 foreach(array_slice($tasks,0,100) as $a){$state=$a->sent_status?:($a->due_at<time()?'closed':'waiting');$out.='<tr><td>'.esc_html($a->subject).'</td><td>'.esc_html($a->title).'</td><td>'.esc_html(dgs_quiz_fmt($a->due_at)).'</td><td>'.dgs_hw_badge($state).'</td><td><a class="dgh-send-link" href="'.esc_url(dgs_hw_url($year,array('hw_task'=>$a->id))).'#dgh-send">'.($state==='revision'?'اصلاح و ارسال مجدد':'مشاهده / ارسال تکلیف').'</a></td></tr>';}
 $out.='</tbody></table></div>';if(!$tasks)$out.='<p class="dgh-help">هنوز تکلیفی برای کلاس شما تعریف نشده است.</p>';if(count($tasks)>100)$out.='<p>۱۰۰ تکلیف آخر نمایش داده می‌شود.</p>';$out.='</section>';
 if($class&&$class->active){$subjects=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT s.id,s.title FROM {$e['teaching']} a JOIN {$e['subjects']} s ON s.id=a.subject_id WHERE a.class_id=%d AND s.active=1 ORDER BY s.title",$class->id));$options=array();$recipients=array();foreach($subjects as $s){$options[$s->id]=$s->title;$recipients[$s->id]=dgs_hw_recipients($uid,$class->id,$s->id,$year);}$subject=$task?(int)$task->subject_id:(int)array_key_first($options);
 $out.='<section class="dgh-card" id="dgh-send"><h3>'.dgs_portal_icon('upload').' ارسال تکلیف جدید</h3><p class="dgh-help">فایل خود را برای معلم مربوطه یا مشاور اختصاصی ارسال کنید.</p>';if($task)$out.='<div class="dgh-task-note"><strong>'.esc_html($task->title).'</strong><p>'.nl2br(esc_html($task->instructions)).'</p><small>مهلت: '.esc_html(dgs_quiz_fmt($task->due_at)).'</small><a href="'.esc_url(dgs_hw_url($year)).'#dgh-send">ارسال مستقل از تکلیف محول‌شده</a></div>';
 if(!$subjects)$out.='<p>هنوز درس و معلمی برای کلاس تعیین نشده است.</p>';else{
 $out.=dgs_hw_form('send',$year).'<input type="hidden" name="request_token" value="'.esc_attr(wp_generate_uuid4()).'"><input type="hidden" name="task_id" value="'.($task?(int)$task->id:0).'"><div class="dgh-three">';
 if($task)$out.='<label>درس<input value="'.esc_attr($options[$subject]??'').'" readonly><input type="hidden" name="subject_id" value="'.$subject.'"></label>';else $out.=dgs_edu_select('subject_id','درس',$options,$subject);
 $out.='<label>عنوان تکلیف<input name="title" maxlength="150" value="'.esc_attr($task?$task->title:'').'" '.($task?'readonly':'').' required></label>'.dgs_edu_select('recipient_id','گیرنده مجاز',$recipients[$subject]??array()).'</div><label class="dgh-drop" data-hw-drop><span class="dgh-upload-icon">'.dgs_portal_icon('upload').'</span><strong>فایل را اینجا رها کنید یا انتخاب کنید</strong><small>PDF، DOCX، XLSX، PPTX، JPG، PNG — حداکثر ۲۰ مگابایت؛ سقف هاست: '.esc_html(size_format(wp_max_upload_size())).'</small><span class="dgh-file-pick">'.dgs_portal_icon('file').' انتخاب فایل</span><input type="file" name="homework_file" accept=".pdf,.docx,.xlsx,.pptx,.jpg,.jpeg,.png" required><span data-hw-file-name></span></label><label>توضیحات (اختیاری)<textarea name="message" rows="3" maxlength="4000"></textarea></label><div class="dgh-actions"><button class="dg-btn">'.dgs_portal_icon('send').' ارسال تکلیف</button></div></form>'.dgs_quiz_script_data('dgh-recipient-data',$recipients);}
 $out.='</section>';}else $out.='<section class="dgh-card" id="dgh-send">برای ارسال، کلاس فعال همان سال باید تعیین شده باشد. سوابق ارسال‌های قبلی حفظ شده‌اند.</section>';
 $history=$wpdb->get_results($wpdb->prepare("SELECT x.*,s.title AS subject FROM {$t['submissions']} x JOIN {$e['subjects']} s ON s.id=x.subject_id WHERE x.student_id=%d AND x.school_year=%s ORDER BY x.id DESC LIMIT 101",$uid,$year));$out.='<section class="dgh-card" id="dgh-history"><h3>'.dgs_portal_icon('history').' سابقه ارسال‌های من</h3>'.dgs_edu_table_start(array('درس','عنوان تکلیف','تاریخ ارسال','وضعیت','بازخورد / نمره','عملیات'));
 foreach(array_slice($history,0,100) as $s)$out.='<tr><td>'.esc_html($s->subject).'</td><td>'.esc_html($s->title).'</td><td>'.esc_html(dgs_quiz_fmt($s->submitted_at)).'</td><td>'.dgs_hw_badge($s->status).'</td><td>'.nl2br(esc_html($s->feedback?:'—')).($s->score!==null?'<small class="dgh-score">نمره: '.esc_html(dgs_fa_digits($s->score/100)).' از ۲۰</small>':'').'</td><td><a href="'.esc_url(dgs_hw_url($year,array('hw_submission'=>$s->id))).'#dgh-file-view">جزئیات و فایل</a></td></tr>';
 $out.='</tbody></table></div>';if(!$history)$out.='<p class="dgh-help">هنوز فایلی ارسال نکرده‌اید.</p>';if(count($history)>100)$out.='<p>۱۰۰ ارسال آخر نمایش داده می‌شود.</p>';$out.='</section>';$selected=dgs_hw_submission(absint(dgs_att_get('hw_submission')));if($selected&&dgs_hw_can_read($selected)&&(int)$selected->student_id===$uid)$out.=dgs_hw_file_panel($selected);return $out;
}
function dgs_hw_scope($year){
 $args=array($year);$where='s.school_year=%s';$uid=get_current_user_id();$e=dgs_edu_tables();if(current_user_can('dgs_manage_education'))return array($where,$args);
 if(dgs_edu_role($uid,'dgs_teacher')){$where.=" AND EXISTS(SELECT 1 FROM {$e['teaching']} a JOIN {$e['classes']} c ON c.id=a.class_id WHERE a.class_id=s.class_id AND a.subject_id=s.subject_id AND a.teacher_id=%d AND c.active=1)";$args[]=$uid;}
 elseif(dgs_edu_role($uid,'dgs_counselor')){$where.=" AND s.recipient_id=%d AND EXISTS(SELECT 1 FROM {$e['counseling']} a WHERE a.student_id=s.student_id AND a.counselor_id=%d AND a.school_year=s.school_year)";$args[]=$uid;$args[]=$uid;}
 else $where.=' AND 1=0';return array($where,$args);
}
function dgs_hw_staff($year){
 global $wpdb;$t=dgs_hw_tables();$e=dgs_edu_tables();list($where,$args)=dgs_hw_scope($year);$classes=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT c.id,c.title,c.grade FROM {$t['submissions']} s JOIN {$e['classes']} c ON c.id=s.class_id WHERE $where ORDER BY c.grade,c.title",$args));$subjects=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT a.id,a.title FROM {$t['submissions']} s JOIN {$e['subjects']} a ON a.id=s.subject_id WHERE $where ORDER BY a.title",$args));$class_opts=array();foreach($classes as $c)$class_opts[$c->id]=dgs_edu_grade_label($c->grade).' — '.$c->title;$sub_opts=array();foreach($subjects as $s)$sub_opts[$s->id]=$s->title;
 $class=absint(dgs_att_get('hw_class'));$subject=absint(dgs_att_get('hw_subject'));$status=dgs_att_get('hw_status');if($class){$where.=' AND s.class_id=%d';$args[]=$class;}if($subject){$where.=' AND s.subject_id=%d';$args[]=$subject;}if(in_array($status,array('pending','reviewed','revision'),true)){$where.=' AND s.status=%s';$args[]=$status;}
 $out=dgs_hw_task_editor($year).'<section class="dgh-card"><form method="get" class="dge-filter" action="'.esc_url(dgs_page_url('portal')).'"><input type="hidden" name="dg_tab" value="homework"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('hw_class','کلاس',$class_opts,$class,false).dgs_edu_select('hw_subject','درس',$sub_opts,$subject,false).dgs_edu_select('hw_status','وضعیت تکلیف',array('pending'=>'در انتظار بررسی','reviewed'=>'بررسی‌شده','revision'=>'نیاز به اصلاح'),$status,false).'<button class="dg-btn">⌕ جست‌وجو</button></form></section>';
 $groups=$wpdb->get_results($wpdb->prepare("SELECT s.status,COUNT(*) AS n FROM {$t['submissions']} s WHERE $where GROUP BY s.status",$args));$counts=array('pending'=>0,'reviewed'=>0,'revision'=>0);foreach($groups as $g)$counts[$g->status]=(int)$g->n;$total=array_sum($counts);$out.='<div class="dgh-stats">';foreach(array(array('کل ارسال‌ها',$total,'all','▤'),array('در انتظار بررسی',$counts['pending'],'pending','◷'),array('بررسی‌شده',$counts['reviewed'],'reviewed','✓'),array('نیاز به اصلاح',$counts['revision'],'revision','↻')) as $stat)$out.='<article class="dgh-stat-'.$stat[2].'"><span>'.$stat[3].'</span><strong>'.esc_html(dgs_fa_digits($stat[1])).'</strong><small>'.$stat[0].'</small></article>';$out.='</div>';
 $page=max(1,min(max(1,(int)ceil($total/20)),absint(dgs_att_get('hw_page','1'))));$query_args=array_merge($args,array(($page-1)*20));$rows=$wpdb->get_results($wpdb->prepare("SELECT s.*,u.display_name,c.title AS class_title,x.title AS subject FROM {$t['submissions']} s JOIN {$wpdb->users} u ON u.ID=s.student_id JOIN {$e['classes']} c ON c.id=s.class_id JOIN {$e['subjects']} x ON x.id=s.subject_id WHERE $where ORDER BY s.id DESC LIMIT 20 OFFSET %d",$query_args));
 $out.='<section class="dgh-card">'.dgs_edu_table_start(array('نام دانش‌آموز','کلاس / درس','عنوان تکلیف','تاریخ ارسال','فایل','وضعیت'));foreach($rows as $s)$out.='<tr><td>'.esc_html($s->display_name).'</td><td>'.esc_html($s->class_title.' / '.$s->subject).'</td><td>'.esc_html($s->title).'</td><td>'.esc_html(dgs_quiz_fmt($s->submitted_at)).'</td><td><a class="dgh-view-link" href="'.esc_url(dgs_hw_url($year,array('hw_submission'=>$s->id,'hw_class'=>$class,'hw_subject'=>$subject,'hw_status'=>$status,'hw_page'=>$page))).'#dgh-review">▤ مشاهده</a></td><td>'.dgs_hw_badge($s->status).'</td></tr>';
 $out.='</tbody></table></div>';if(!$rows)$out.='<p class="dgh-help">ارسالی با این فیلترها وجود ندارد.</p>';$out.='<nav class="dge-pagination">';foreach(array(-1=>'قبلی',1=>'بعدی') as $delta=>$label)if($page+$delta>0&&$page+$delta<=ceil($total/20))$out.='<a href="'.esc_url(dgs_hw_url($year,array('hw_page'=>$page+$delta,'hw_class'=>$class,'hw_subject'=>$subject,'hw_status'=>$status))).'">'.$label.'</a>';$out.='<span>'.esc_html(dgs_fa_digits($page)).'</span></nav></section>';
 $selected=dgs_hw_submission(absint(dgs_att_get('hw_submission')));if($selected&&dgs_hw_can_review($selected))$out.=dgs_hw_review_panel($selected,$year);return $out;
}
function dgs_hw_task_editor($year){
 if(!current_user_can('dgs_manage_education')&&!dgs_edu_role(get_current_user_id(),'dgs_teacher'))return '';$pairs=dgs_grade_pairs($year);$options=array();foreach($pairs as $p)$options[$p->class_id.':'.$p->subject_id]=$p->title.' — '.$p->subject;if(!$options)return '';
 $task=dgs_hw_task(absint(dgs_att_get('hw_task')));if($task&&($task->school_year!==$year||!dgs_grade_can_edit(dgs_edu_class($task->class_id),$task->subject_id)))$task=null;$date=$task?$task->due_at:time()+86400;$out='<details class="dgh-card dgh-task-editor" '.($task?'open':'').'><summary>＋ '.($task?'ویرایش تکلیف محول‌شده':'تعریف تکلیف برای کلاس').'</summary>'.dgs_hw_form('task',$year).'<input type="hidden" name="task_id" value="'.($task?(int)$task->id:0).'"><input type="hidden" name="revision" value="'.($task?(int)$task->revision:0).'"><div class="dgh-three">'.dgs_edu_select('hw_pair','کلاس و درس',$options,$task?$task->class_id.':'.$task->subject_id:array_key_first($options)).'<label>عنوان تکلیف<input name="title" maxlength="150" value="'.esc_attr($task?$task->title:'').'" required></label><label>تاریخ مهلت (شمسی)<input name="due_date" dir="ltr" value="'.esc_attr(dgs_att_jdate(wp_date('Y-m-d',$date))).'" required></label><label>ساعت مهلت (۲۴ساعته)<input name="due_time" dir="ltr" placeholder="18:30" pattern="([01][0-9]|2[0-3]):[0-5][0-9]" value="'.esc_attr(wp_date('H:i',$date)).'" required></label>'.dgs_edu_select('active','وضعیت',array(1=>'فعال',0=>'بایگانی'),$task?$task->active:1).'</div><label>شرح و دستور تکلیف<textarea name="instructions" rows="3" maxlength="4000">'.esc_textarea($task?$task->instructions:'').'</textarea></label><p class="dgh-help">زمان‌ها به وقت '.esc_html(wp_timezone_string()).'. بایگانی، سابقه فایل‌های ارسال‌شده را حذف نمی‌کند.</p><button class="dg-btn">✓ ذخیره تکلیف</button></form></details>';
 global $wpdb;$t=dgs_hw_tables();$allowed=array();foreach($pairs as $p)$allowed[]='(class_id='.(int)$p->class_id.' AND subject_id='.(int)$p->subject_id.')';$tasks=$wpdb->get_results($wpdb->prepare("SELECT id,title,due_at,active FROM {$t['tasks']} WHERE school_year=%s AND (".implode(' OR ',$allowed).') ORDER BY id DESC LIMIT 100',$year));if($tasks){$out.='<details class="dgh-card"><summary>تکالیف تعریف‌شده و ویرایش مهلت</summary><ul class="dgh-task-links">';foreach($tasks as $a)$out.='<li><a href="'.esc_url(dgs_hw_url($year,array('hw_task'=>$a->id))).'">'.esc_html($a->title).'</a><small>'.esc_html(dgs_quiz_fmt($a->due_at)).($a->active?'':' — بایگانی').'</small></li>';$out.='</ul></details>';}return $out;
}
function dgs_hw_file_panel($s){
 if(!dgs_hw_can_read($s))return '';$out='<section class="dgh-card dgh-file-panel" id="dgh-file-view"><h3>▤ مشاهده فایل تکلیف</h3><div class="dgh-file-title"><span>▤</span><div><strong>'.esc_html($s->file_name).'</strong><small>'.esc_html(size_format($s->file_size)).'</small></div></div>';
 if($s->message)$out.='<p class="dgh-message">'.nl2br(esc_html($s->message)).'</p>';
 if($s->file_mime==='application/pdf')$out.='<iframe loading="lazy" title="فایل تکلیف" src="'.esc_url(dgs_hw_file_url($s->id)).'"></iframe>';
 elseif(in_array($s->file_mime,array('image/png','image/jpeg'),true))$out.='<img src="'.esc_url(dgs_hw_file_url($s->id)).'" alt="فایل تکلیف">';
 else $out.='<p class="dgh-help">برای مشاهده فایل Office آن را دانلود کنید.</p>';
 $out.='<a class="dg-btn" href="'.esc_url(dgs_hw_file_url($s->id,true)).'">↓ دانلود فایل</a>';return $out.'</section>';
}
function dgs_hw_review_panel($s,$year){
 if(!dgs_hw_can_review($s))return '';$u=get_userdata($s->student_id);$out='<div class="dgh-review-grid" id="dgh-review">'.dgs_hw_file_panel($s).'<section class="dgh-card"><h3>'.dgs_portal_icon('message').' ارزیابی و بازخورد</h3><p>'.esc_html($u?$u->display_name:'').': '.esc_html($s->title).'</p>'.dgs_hw_form('review',$year).'<input type="hidden" name="submission_id" value="'.(int)$s->id.'"><input type="hidden" name="revision" value="'.(int)$s->revision.'"><label>بازخورد (برای نیاز به اصلاح الزامی)<textarea name="feedback" maxlength="4000" rows="6">'.esc_textarea($s->feedback).'</textarea></label><label>نمره اختیاری از ۲۰<input name="score" type="number" min="0" max="20" step="0.01" value="'.esc_attr($s->score===null?'':$s->score/100).'"></label><fieldset class="dgh-review-status"><legend>وضعیت بررسی</legend>';
 foreach(array('reviewed'=>'بررسی‌شده','revision'=>'نیاز به اصلاح') as $value=>$label)$out.='<label><input type="radio" name="status" value="'.$value.'" '.checked($s->status==='revision'?'revision':'reviewed',$value,false).' required><span>'.$label.'</span></label>';
 return $out.'</fieldset><div class="dgh-actions"><button class="dg-btn">✓ ثبت نتیجه</button><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_hw_url($year)).'">انصراف</a></div></form></section></div>';
}
add_filter('body_class',function($classes){if(dgs_is_role_portal()&&dgs_portal_tab()==='homework')$classes[]='dgs-homework-page';return $classes;});
add_action('wp_enqueue_scripts',function(){if(!dgs_is_role_portal()||dgs_portal_tab()!=='homework')return;wp_register_style('dgs-homework',false,array(),DGS_VERSION);wp_enqueue_style('dgs-homework');wp_add_inline_style('dgs-homework',file_get_contents(DGS_PATH.'assets/homework.css'));wp_register_script('dgs-homework',false,array(),DGS_VERSION,true);wp_enqueue_script('dgs-homework');wp_add_inline_script('dgs-homework',file_get_contents(DGS_PATH.'assets/homework.js'));});
